package ingest

import (
	"net/http"

	"github.com/PMPRR/SCOM---Trabalho-2/internal/service"
)

// Credentials are the secrets of the sources that need one. They come from
// the environment; an empty field leaves the source off.
type Credentials struct {
	InmetToken string

	// CEMADEN accepts either an e-mail and password, with which the token is
	// obtained and renewed automatically, or a token generated by hand, which
	// stops working when it expires (about four hours).
	CemadenEmail    string
	CemadenPassword string
	CemadenToken    string
}

// Sources returns the sources enabled by the configuration. Open-Meteo and
// the METAR reports need no credential and are always on.
func Sources(client *http.Client, creds Credentials) []service.Source {
	sources := []service.Source{NewNOAA(client), NewOpenMeteo(client)}
	if creds.InmetToken != "" {
		sources = append(sources, NewINMET(client, creds.InmetToken))
	}
	if creds.CemadenToken != "" || (creds.CemadenEmail != "" && creds.CemadenPassword != "") {
		sources = append(sources, NewCEMADEN(client, creds.CemadenEmail, creds.CemadenPassword, creds.CemadenToken))
	}
	return sources
}
